fn longest_increasing_streak(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }

    let mut best: usize = 1;
    let mut cur: usize = 1;

    for i in 1..nums.len() {
        if nums[i] > nums[i - 1] {
            cur += 1;
        } else {
            cur = 1;
        }
        if cur > best {
            best = cur;
        }
    }

    best
}